compile.workshop:
settings
{
	main
	{
		Description: "Some awesome game mode"
	}
	modes
	{
		Skirmish
		{
			enabled maps
			{
				Workshop Island
			}
		}
		General
		{
			Hero Limit: Off
			Respawn Time Scalar: 30%
		}
	}
}

variables {
    global:
        8: I
    player:
        0: dmgDealt
        1: textPos
        2: velocity
        3: angle
        4: xMultiplier
        5: timeOffsets
        6: colors
        7: textIndex
        8: time
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, dmgDealt, Empty Array);
        Set Player Variable(Event Player, textPos, Empty Array);
        Set Player Variable(Event Player, velocity, Empty Array);
        Set Player Variable(Event Player, angle, Empty Array);
        Set Player Variable(Event Player, xMultiplier, Empty Array);
        Set Player Variable(Event Player, timeOffsets, Empty Array);
        Set Player Variable(Event Player, colors, Empty Array);
    }
}

rule ("dummy") {
    event {
        Ongoing - Global;
    }
    actions {
        Create Dummy Bot(Hero(Torbjörn), Team 2, -1, Null, Null);
        Create HUD Text(All Players(All Teams), Custom String("load: {0}, avg: {1}, max: {2}", Server Load, Server Load Average, Server Load Peak), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
    }
}

rule ("text") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Event Player == Host Player;
        Has Spawned(Event Player) == True;
    }
    actions {
        Wait(1, Ignore Condition);
        Chase Player Variable At Rate(Host Player, time, 9999, 1, None);
        For Global Variable(I, 0, 25, 1);
            Create In-World Text(If-Then-Else(And(Compare(Subtract((Local Player).time, Value In Array((Local Player).timeOffsets, Evaluate Once(Global.I))), >=, 0), Compare(Subtract((Local Player).time, Value In Array((Local Player).timeOffsets, Evaluate Once(Global.I))), <=, 0.7)), Local Player, Null), Custom String(" {0} ", Value In Array((Local Player).dmgDealt, Evaluate Once(Global.I))), Update Every Frame(Add(Add(Value In Array((Local Player).textPos, Evaluate Once(Global.I)), Vector(0, Divide(Multiply(Subtract(Multiply(Multiply(Value In Array((Local Player).velocity, Evaluate Once(Global.I)), Subtract((Local Player).time, Value In Array((Local Player).timeOffsets, Evaluate Once(Global.I)))), Sine From Degrees(Value In Array((Local Player).angle, Evaluate Once(Global.I)))), Multiply(Multiply(15, Subtract((Local Player).time, Value In Array((Local Player).timeOffsets, Evaluate Once(Global.I)))), Subtract((Local Player).time, Value In Array((Local Player).timeOffsets, Evaluate Once(Global.I))))), Distance Between(Eye Position(Local Player), Value In Array((Local Player).textPos, Evaluate Once(Global.I)))), 10), 0)), Divide(Multiply(Multiply(Multiply(Multiply(Multiply(World Vector Of(Left, Local Player, Rotation), Value In Array((Local Player).xMultiplier, Evaluate Once(Global.I))), Value In Array((Local Player).velocity, Evaluate Once(Global.I))), Subtract((Local Player).time, Value In Array((Local Player).timeOffsets, Evaluate Once(Global.I)))), Cosine From Degrees(Value In Array((Local Player).angle, Evaluate Once(Global.I)))), Distance Between(Eye Position(Local Player), Value In Array((Local Player).textPos, Evaluate Once(Global.I)))), 10))), 2, Do Not Clip, Visible To Position String and Color, Value In Array((Local Player).colors, Evaluate Once(Global.I)), Visible Always);
        End;
    }
}

rule ("hp") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Wait(5, Ignore Condition);
        Start Heal Over Time(Event Player, Null, 9999, 9999);
    }
}

rule ("dmg") {
    event {
        Player Dealt Damage;
        Team 1;
        All;
    }
    actions {
        Set Player Variable At Index(Attacker, dmgDealt, (Attacker).textIndex, Event Damage);
        Set Player Variable At Index(Attacker, colors, (Attacker).textIndex, Custom Color(255, Max(Subtract(255, Multiply(512, Divide(Event Damage, Max Health(Victim)))), 21), Absolute Value(Subtract(255, Multiply(1024, Divide(Event Damage, Max Health(Victim))))), 255));
        Set Player Variable At Index(Attacker, textPos, (Attacker).textIndex, Eye Position(Victim));
        Set Player Variable At Index(Attacker, velocity, (Attacker).textIndex, Random Real(9, 12));
        Set Player Variable At Index(Attacker, angle, (Attacker).textIndex, Random Real(50, 70));
        "attacker.direction[attacker.textIndex] = angleToDirection(random.uniform(0, 360), 0)"
        Set Player Variable At Index(Attacker, xMultiplier, (Attacker).textIndex, Multiply(Random Real(1, 0.5), If-Then-Else(Random Integer(0, 1), -1, 1)));
        Set Player Variable At Index(Attacker, timeOffsets, (Attacker).textIndex, (Attacker).time);
        Modify Player Variable(Attacker, textIndex, Add, 1);
        Modify Player Variable(Attacker, textIndex, Modulo, 25);
    }
}

